// --- Call Graph Helpers ---
function resetCallGraphView() {
    currentGraphLines.forEach(line => line.remove());
    currentGraphLines = [];

    if (callGraphPlaceholderEl) {
        callGraphPlaceholderEl.innerHTML = '';
        callGraphPlaceholderEl.classList.remove('hidden');
