    font-size: 0.85rem;
}

.node-details li {
    margin: 4px 0;
}

/* ========================================
   LIGHT THEME CONTRAST FIXES
   ======================================== */

/* Fix 1 & 2: Analytics preview backgrounds - lighter for better green contrast */
[data-theme="light"] .eti-container {
    background: linear-gradient(135deg, rgba(255, 71, 87, 0.05) 0%, rgba(255, 165, 2, 0.05) 100%);
    border-color: rgba(255, 71, 87, 0.2);
}

[data-theme="light"] .modeler-container {
    background: linear-gradient(135deg, rgba(90, 156, 248, 0.05) 0%, rgba(38, 222, 129, 0.05) 100%);
    border-color: rgba(90, 156, 248, 0.2);
}

/* Fix 3: Theme toggle button text - darker for contrast */
[data-theme="light"] .theme-toggle {
    color: #1a1f2e;
    background: rgba(255, 255, 255, 0.8);
    border-color: rgba(46, 214, 15, 0.4);
}

/* Fix 4: Daily Analysis chart - darker labels and grid (handled in JS via CSS vars) */
[data-theme="light"] {
    --chart-text-color: #374151;
    --chart-grid-color: rgba(0, 0, 0, 0.12);
}

:root {
    --chart-text-color: #9ca3af;
    --chart-grid-color: rgba(255, 255, 255, 0.1);
}

/* Fix 5: Chart container labels - darker in light theme */
[data-theme="light"] .chart-header h2,
[data-theme="light"] .chart-header {
    color: #1a1f2e;
}

/* Fix 6: Threat Vector Correlation header - darker */
[data-theme="light"] .correlation-header h2 {
    color: #1a1f2e;
}

[data-theme="light"] .correlation-subtitle {
    color: #4a5568;
}

/* Fix 7: ETI subtitle and summary - darker for better contrast */
[data-theme="light"] .eti-subtitle {
    color: #4a5568;
}

[data-theme="light"] .eti-summary {
    color: #374151;
}

/* Fix 8: Prediction labels in threat modeler - darker */
[data-theme="light"] .modeler-subtitle {
    color: #4a5568;
}

[data-theme="light"] .modeler-field label {
    color: #374151;
}

[data-theme="light"] .modeler-hint {
    color: #6b7280;
}

/* Fix 9: Analytics preview backgrounds - much lighter for green text visibility */
[data-theme="light"] .preview-box {
    background: rgba(255, 255, 255, 0.6);
    border-color: rgba(46, 214, 15, 0.3);
}

/* Fix 10: ETI item text - lighter for better readability */
[data-theme="light"] .eti-count {
    color: #6b7280;
}

[data-theme="light"] .eti-name {
    color: #1f2937;
}

/* Fix 11: Make ETI details much more visible in light theme */
[data-theme="light"] .eti-details {
    color: #437ed1;
    font-weight: 500;
}

/* Fix 12: Threat ticker text visibility in light theme */
[data-theme="light"] .ticker-item {
    color: #374151;
    font-weight: 500;
}

/* Back to Top Button */
.back-to-top {
    position: fixed;
    bottom: 30px;
    right: 30px;
    width: 50px;
    height: 50px;
    background: linear-gradient(135deg, var(--accent-green), var(--accent-green-dim));
    border: 2px solid var(--accent-green);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 9998;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    box-shadow: 0 4px 20px var(--success-glow);
    color: #000;
    font-size: 1.2rem;
}

.back-to-top.visible {
    opacity: 1;
    visibility: visible;
}

.back-to-top:hover {
    transform: translateY(-5px) scale(1.1);
    box-shadow: 0 6px 30px var(--success-glow);
}

.back-to-top:active {
    transform: translateY(-2px) scale(1.05);
}

[data-theme="light"] .back-to-top {
    background: linear-gradient(135deg, #2ed60f, #27b00c);
    color: #fff;
}

:root {
    --bg-primary: #000000;
    --bg-secondary: #0a0a0a;
    --bg-card: #0f0f0f;
    --bg-hover: #151515;
    --text-primary: #e8f0e8;
    --text-secondary: #9ca3af;
    --accent-green: #20be65;
    --accent-green-dim: #3ea874;
    --accent-yellow: #ffd700;
    --accent-red: #ff3b3b;
    --accent-red-dim: #cc2f2f;
    --border-color: #1a1a1a;
    --shadow-color: rgba(0, 0, 0, 0.5);
    --success-glow: rgba(57, 255, 20, 0.3);
    --danger-glow: rgba(255, 59, 59, 0.3);
    --warning-glow: rgba(255, 215, 0, 0.3);
    /* Chart theming */
    --chart-text-color: #9ca3af;
    --chart-grid-color: rgba(255, 255, 255, 0.1);
}

[data-theme="light"] {
    --bg-primary: #f0f4f0;
    --bg-secondary: #ffffff;
    --bg-card: #fafafa;
    --bg-hover: #e8f5e8;
    --text-primary: #1a1f2e;
    --text-secondary: #4a5568;
    --accent-green: #20be65;
    --accent-green-dim: #3ea874;
    --accent-yellow: #cc9a00;
    --accent-red: #dc2626;
    --accent-red-dim: #b91c1c;
    --border-color: #d1d5db;
    --shadow-color: rgba(0, 0, 0, 0.1);
    --success-glow: rgba(46, 214, 15, 0.2);
    --danger-glow: rgba(220, 38, 38, 0.2);
    --warning-glow: rgba(204, 154, 0, 0.2);
    /* Chart theming overrides for light mode */
    --chart-text-color: #1f2937; /* gray-800 for maximum contrast */
    --chart-grid-color: rgba(0, 0, 0, 0.12);
}

* { 
    margin: 0; 
    padding: 0; 
    box-sizing: border-box; 
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    min-height: 100vh;
    margin: 0;
    overflow-x: hidden;
    position: relative;
}

body::before {
    content: '';
    position: fixed;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: 
        radial-gradient(circle at 20% 50%, rgba(57, 255, 20, 0.08) 0%, transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(57, 255, 20, 0.06) 0%, transparent 50%),
        radial-gradient(circle at 40% 20%, rgba(57, 255, 20, 0.05) 0%, transparent 50%);
    animation: backgroundGlow 15s ease-in-out infinite;
    pointer-events: none;
    z-index: 0;
}

@keyframes backgroundGlow {
    0%, 100% { 
        transform: translate(0, 0) scale(1);
        opacity: 0.4;
    }
    33% { 
        transform: translate(10%, 10%) scale(1.1);
        opacity: 0.6;
    }
    66% { 
        transform: translate(-10%, 5%) scale(0.95);
        opacity: 0.5;
    }
}

body > * {
    position: relative;
    z-index: 1;
}

/* Side Panel Navigation */
.side-panel {
    position: fixed;
    left: 0;
    top: 0;
    height: 100vh;
    width: 70px;
    background: rgba(10, 10, 10, 0.92);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border-right: 1px solid rgba(57, 255, 20, 0.2);
    box-shadow: 0 0 30px rgba(57, 255, 20, 0.1);
    display: flex;
    flex-direction: column;
    align-items: center;
    z-index: 9999;
    transition: all 0.3s ease;
}

.side-panel:hover {
    background: rgba(15, 15, 15, 0.8);
    box-shadow: 0 0 40px rgba(57, 255, 20, 0.2);
}

.panel-icon-strip {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 2rem 0;
}

.panel-logo-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    color: var(--accent-green);
    font-size: 2rem;
    animation: pulse-glow 3s ease-in-out infinite;
    cursor: pointer;
    transition: all 0.3s ease;
}

.panel-logo-icon:hover {
    transform: scale(1.1);
    filter: drop-shadow(0 0 20px var(--success-glow));
}

@keyframes pulse-glow {
    0%, 100% { filter: drop-shadow(0 0 5px var(--success-glow)); }
    50% { filter: drop-shadow(0 0 15px var(--success-glow)) drop-shadow(0 0 25px var(--success-glow)); }
}

/* Graphs Preview Grid */
.graphs-preview {
    position: fixed;
    left: 70px;
    top: 50%;
    transform: translateY(-50%) translateX(-100%);
    background: rgba(10, 10, 10, 0.92);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(57, 255, 20, 0.3);
    border-left: none;
    border-radius: 0 12px 12px 0;
    padding: 2rem;
    width: 480px;
    max-height: 90vh;
    overflow-y: auto;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.3s ease, visibility 0.3s;
    box-shadow: 5px 0 40px rgba(57, 255, 20, 0.15);
    z-index: 9998;
    will-change: transform, opacity;
}

.graphs-preview::-webkit-scrollbar {
    width: 6px;
}

.graphs-preview::-webkit-scrollbar-track {
    background: var(--bg-secondary);
    border-radius: 3px;
}

.graphs-preview::-webkit-scrollbar-thumb {
    background: var(--accent-green);
    border-radius: 3px;
}

.graphs-preview.show {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateY(-50%) translateX(0);
}

.preview-header {
    margin-bottom: 1rem;
    padding-bottom: 0.8rem;
    border-bottom: 1px solid var(--border-color);
}

.preview-header h3 {
    color: var(--accent-green);
    font-size: 1.1rem;
    margin-bottom: 0.3rem;
}

.preview-header p {
    color: var(--text-secondary);
    font-size: 0.85rem;
}

/* Analytics Miniview - Scaled down live view */
.analytics-miniview {
    position: relative;
    width: 100%;
    height: 70vh;
    background: var(--bg-secondary);
    border: 2px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: all 0.3s ease;
}

.analytics-miniview:hover {
    border-color: var(--accent-green);
    box-shadow: 0 0 30px var(--success-glow);
}

.miniview-content {
    width: 100%;
    height: 100%;
    transform-origin: top left;
    transform: scale(0.25);
    width: 400%;
    height: 400%;
    pointer-events: none;
    overflow: hidden;
}

.miniview-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 14, 20, 0.7);
    backdrop-filter: blur(1px);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    opacity: 0;
    transition: opacity 0.3s ease;
    pointer-events: none;
}

.analytics-miniview:hover .miniview-overlay {
    opacity: 1;
}

.miniview-overlay i {
    font-size: 3rem;
    color: var(--accent-green);
    animation: pulse-scale 2s ease-in-out infinite;
}

.miniview-overlay span {
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--text-primary);
    text-transform: uppercase;
    letter-spacing: 1px;
}
.preview-home-nav {
    margin-top: 1.5rem;
    padding: 1rem;
    background: var(--bg-secondary);
    border: 2px solid var(--border-color);
    border-radius: 10px;
    display: flex;
    align-items: center;
    gap: 0.8rem;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    opacity: 0;
    visibility: hidden;
    transform: translateY(10px);
}

.preview-home-nav.visible {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.preview-home-nav:hover {
    background: var(--bg-hover);
    border-color: var(--accent-green);
    box-shadow: 0 5px 20px var(--success-glow);
    transform: translateY(-2px);
}

.preview-home-nav i {
    font-size: 1.5rem;
    color: var(--accent-green);
}

.preview-home-nav span {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-primary);
}

.preview-label {
    flex: 1;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--text-primary);
    letter-spacing: 0.3px;
}

/* Analytics Miniview - Screenshot preview */
.analytics-miniview {
    position: relative;
    width: 100%;
    height: 70vh;
    background: var(--bg-secondary);
    border: 2px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: all 0.3s ease;
    padding: 1.5rem;
}

.analytics-miniview:hover {
    border-color: var(--accent-green);
    box-shadow: 0 0 30px var(--success-glow);
}

.miniview-preview {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    opacity: 0.7;
}

.preview-row {
    display: flex;
    gap: 1rem;
    flex: 1;
}

.preview-box {
    flex: 1;
    background: rgba(15, 15, 15, 0.5);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(57, 255, 20, 0.2);
    border-radius: 6px;
    position: relative;
    overflow: hidden;
    padding: 0.5rem;
}

.preview-box.large {
    flex: 2;
}

.preview-box.wide {
    flex: 1;
    min-height: 150px;
}

.box-header {
    font-size: 0.65rem;
    color: var(--accent-green);
    margin-bottom: 0.5rem;
    opacity: 0.8;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.box-content {
    height: calc(100% - 1.5rem);
    position: relative;
}

.map-visual {
    background: radial-gradient(circle at center, rgba(57, 255, 20, 0.05), transparent);
    position: relative;
}

.map-dot {
    position: absolute;
    width: 8px;
    height: 8px;
    background: var(--accent-green);
    border-radius: 50%;
    box-shadow: 0 0 10px var(--accent-green);
    animation: map-pulse 2s ease-in-out infinite;
}

.map-dot:nth-child(2) { animation-delay: 0.5s; }
.map-dot:nth-child(3) { animation-delay: 1s; }

@keyframes map-pulse {
    0%, 100% { transform: scale(1); opacity: 0.6; }
    50% { transform: scale(1.5); opacity: 1; }
}

.chart-visual {
    display: flex;
    align-items: flex-end;
    justify-content: space-around;
    height: 100%;
    padding: 0.5rem;
    gap: 0.3rem;
}

.chart-bar {
    flex: 1;
    background: linear-gradient(180deg, var(--accent-green), transparent);
    border-radius: 2px;
    animation: bar-grow 2s ease-in-out infinite;
    opacity: 0.7;
}

.chart-bar:nth-child(2) { animation-delay: 0.2s; }
.chart-bar:nth-child(3) { animation-delay: 0.4s; }
.chart-bar:nth-child(4) { animation-delay: 0.6s; }

@keyframes bar-grow {
    0%, 100% { transform: scaleY(0.8); }
    50% { transform: scaleY(1); }
}

.list-visual {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    padding: 0.3rem;
}

.list-item {
    height: 0.4rem;
    background: linear-gradient(90deg, var(--accent-green), transparent);
    border-radius: 2px;
    opacity: 0.6;
    animation: list-fade 3s ease-in-out infinite;
}

.list-item:nth-child(2) { animation-delay: 0.5s; width: 80%; }
.list-item:nth-child(3) { animation-delay: 1s; width: 60%; }

@keyframes list-fade {
    0%, 100% { opacity: 0.4; }
    50% { opacity: 0.8; }
}

.network-visual {
    position: relative;
    height: 100%;
}

.network-node {
    position: absolute;
    width: 6px;
    height: 6px;
    background: var(--accent-green);
    border-radius: 50%;
    box-shadow: 0 0 8px var(--accent-green);
    animation: node-pulse 3s ease-in-out infinite;
}

.network-node:nth-child(2) { animation-delay: 0.7s; }
.network-node:nth-child(3) { animation-delay: 1.4s; }

@keyframes node-pulse {
    0%, 100% { transform: scale(1); opacity: 0.5; }
    50% { transform: scale(1.3); opacity: 1; }
}

.heat-visual {
    background: 
        radial-gradient(circle at 30% 30%, rgba(57, 255, 20, 0.3), transparent 40%),
        radial-gradient(circle at 70% 60%, rgba(57, 255, 20, 0.2), transparent 40%),
        radial-gradient(circle at 50% 80%, rgba(57, 255, 20, 0.25), transparent 40%);
    animation: heat-shift 4s ease-in-out infinite;
}

@keyframes heat-shift {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 0.8; }
}

.pie-visual {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
}

.pie-chart {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: conic-gradient(
        var(--accent-green) 0deg 120deg,
        var(--accent-yellow) 120deg 240deg,
        var(--accent-red) 240deg 360deg
    );
    box-shadow: 0 0 15px rgba(57, 255, 20, 0.4);
    animation: pie-spin 10s linear infinite;
}

@keyframes pie-spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

.miniview-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 14, 20, 0.7);
