    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    opacity: 0;
    transition: opacity 0.3s ease;
    pointer-events: none;
}

.analytics-miniview:hover .miniview-overlay {
    opacity: 1;
}

.miniview-overlay i {
    font-size: 3rem;
    color: var(--accent-green);
    animation: pulse-scale 2s ease-in-out infinite;
}

.miniview-overlay span {
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--text-primary);
    text-transform: uppercase;
    letter-spacing: 1px;
}

/* Main Content Area */
.main-content {
    margin-left: 70px;
    min-height: 100vh;
    padding: 2rem;
    transition: margin-left 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
}

/* Backdrop overlay for preview panel */
.preview-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.4);
    backdrop-filter: blur(2px);
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    z-index: 9998;
    pointer-events: none;
}

.preview-backdrop.show {
    opacity: 1;
    visibility: visible;
}

/* View Containers */
.view-container {
    display: none;
    animation: fadeIn 0.4s ease-in-out;
}

.view-container.active {
    display: block;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Dashboard Header */
.dashboard-header {
    text-align: center;
    margin-bottom: 2.5rem;
}

.header-content h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    color: var(--accent-green);
    font-weight: 700;
    letter-spacing: 2px;
}

.header-content .subtitle {
    font-size: 1.2rem;
    color: var(--text-secondary);
    font-weight: 500;
}

.pulse-icon {
    display: inline-block;
    animation: pulse-scale 2s ease-in-out infinite;
}

@keyframes pulse-scale {
    0%, 100% {
        transform: scale(1);
        filter: drop-shadow(0 0 5px var(--success-glow));
    }
    50% {
        transform: scale(1.05);
        filter: drop-shadow(0 0 15px var(--success-glow));
    }
}

/* Animations */
.animate-slide-in {
    animation: slideIn 0.6s ease-out;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(-30px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

.animate-fade-in {
    animation: fadeInUp 0.6s ease-out;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.container {
    max-width: 1400px;
    margin: 0 auto;
}

/* Theme Toggle Button */
.theme-toggle {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 10000;
    background: rgba(15, 15, 15, 0.85);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(57, 255, 20, 0.3);
    border-radius: 50px;
    padding: 10px 20px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 1rem;
    color: var(--text-primary);
    transition: all 0.3s ease;
    box-shadow: 0 4px 20px rgba(57, 255, 20, 0.2);
    font-weight: 600;
}

.theme-toggle:hover {
    background: rgba(15, 15, 15, 0.8);
    border-color: var(--accent-green);
    box-shadow: 0 0 30px var(--success-glow);
    transform: translateY(-2px);
}

.theme-toggle .icon {
    font-size: 1.2rem;
}

/* Auto-scroll indicators */
.scroll-indicator {
    position: fixed;
    left: 50%;
    transform: translateX(-50%);
    width: 60px;
    height: 60px;
    background: rgba(57, 255, 20, 0.15);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 2px solid rgba(57, 255, 20, 0.3);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
    z-index: 10001;
}

.scroll-indicator.visible {
    opacity: 1;
    animation: scroll-pulse 1.5s ease-in-out infinite;
}

.scroll-indicator.scroll-up {
    top: 20px;
}

.scroll-indicator.scroll-down {
    bottom: 20px;
}

.scroll-indicator i {
    font-size: 1.5rem;
    color: var(--accent-green);
    animation: scroll-bounce 1s ease-in-out infinite;
}

.scroll-up i {
    animation-name: scroll-bounce-up;
}

.scroll-down i {
    animation-name: scroll-bounce-down;
}

@keyframes scroll-pulse {
    0%, 100% {
        box-shadow: 0 0 10px rgba(57, 255, 20, 0.3);
    }
    50% {
        box-shadow: 0 0 25px rgba(57, 255, 20, 0.6);
    }
}

@keyframes scroll-bounce-up {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-5px);
    }
}

@keyframes scroll-bounce-down {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(5px);
    }
}

/* Threat Ticker */
.threat-ticker-container {
    background: var(--bg-secondary);
    border: 2px solid var(--accent-green);
    border-radius: 8px;
    padding: 12px;
    margin-bottom: 2rem;
    display: flex;
    align-items: center;
    gap: 16px;
    overflow: hidden;
    box-shadow: 0 2px 8px var(--success-glow);
}

.ticker-label {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    background: linear-gradient(135deg, #ff4757, #ff6348);
    border-radius: 6px;
    font-weight: 700;
    font-size: 0.75rem;
    color: #fff;
    white-space: nowrap;
    box-shadow: 0 2px 8px rgba(255, 71, 87, 0.4);
}

.ticker-label i {
    animation: pulse-broadcast 2s infinite;
}

@keyframes pulse-broadcast {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.6; transform: scale(0.9); }
}

.threat-ticker {
    flex: 1;
    overflow: hidden;
    position: relative;
}

.ticker-content {
    display: flex;
    gap: 40px;
    white-space: nowrap;
    animation: scroll-ticker 30s linear infinite;
}

.ticker-content:hover {
    animation-play-state: paused;
}

@keyframes scroll-ticker {
    0% { transform: translateX(0); }
    100% { transform: translateX(-50%); }
}

.ticker-item {
    color: #e0e0e0;
    font-size: 0.9rem;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.ticker-item i {
    font-size: 0.5rem;
    animation: blink 1.5s infinite;
}

@keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
}

/* Notification System */
.notification-container {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 10000;
    display: flex;
    flex-direction: column;
    gap: 12px;
    max-width: 400px;
}

.threat-notification {
    background: rgba(30, 30, 30, 0.98);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-left: 4px solid #ff4757;
    border-radius: 8px;
    padding: 16px;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
    transform: translateX(450px);
    opacity: 0;
    transition: all 0.3s ease-out;
}

.threat-notification.show {
    transform: translateX(0);
    opacity: 1;
}

.notification-icon {
    font-size: 1.5rem;
    flex-shrink: 0;
}

.notification-content {
    flex: 1;
}

.notification-title {
    font-size: 0.95rem;
    color: #e0e0e0;
    margin-bottom: 4px;
}

.notification-title strong {
    text-transform: uppercase;
    font-weight: 800;
}

.notification-details {
    font-size: 0.85rem;
    color: #b0b0b0;
    margin-bottom: 6px;
}

.notification-meta {
    font-size: 0.75rem;
    color: #888;
    display: flex;
    align-items: center;
    gap: 6px;
}

.notification-close {
    cursor: pointer;
    color: #666;
    transition: color 0.2s;
    font-size: 0.9rem;
}

.notification-close:hover {
    color: #e0e0e0;
}

/* Stat Card Pulse Animation */
.stat-pulse {
    animation: stat-pulse-animation 0.6s ease-out;
}

@keyframes stat-pulse-animation {
    0% { transform: scale(1); }
    50% { transform: scale(1.05); box-shadow: 0 8px 24px rgba(90, 156, 248, 0.4); }
    100% { transform: scale(1); }
}

h1 {
    font-size: 2.5rem;
    color: #5a9cf8;
    margin-bottom: 0.5rem;
}

.subtitle {
    color: #888;
    font-size: 1.1rem;
}

.stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5rem;
    margin-bottom: 3rem;
}

.stat-card {
    background: var(--bg-card);
    border: 2px solid var(--border-color);
    border-radius: 12px;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.8rem;
    position: relative;
    overflow: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.stat-card::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, var(--accent-green) 0%, transparent 70%);
    opacity: 0;
    transition: opacity 0.4s ease;
}

.stat-card:hover::before {
    opacity: 0.05;
}

.stat-card:hover {
    transform: translateY(-5px) scale(1.02);
    border-color: var(--accent-green);
    box-shadow: 0 10px 30px var(--success-glow);
}

.stat-card i {
    font-size: 2.5rem;
    opacity: 0.8;
    transition: all 0.3s ease;
}

.stat-card:hover i {
    transform: scale(1.1) rotateY(180deg);
    opacity: 1;
}

.stat-number {
    font-size: 2.5rem;
    font-weight: 700;
    transition: all 0.3s ease;
}

.stat-card:hover .stat-number {
    transform: scale(1.1);
    text-shadow: 0 0 20px currentColor;
}

.stat-label {
    font-size: 0.9rem;
    color: var(--text-secondary);
    font-weight: 600;
}

.stat-glow {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, transparent, var(--accent-green), transparent);
    opacity: 0;
    transition: opacity 0.4s ease;
}

.stat-card:hover .stat-glow {
    opacity: 1;
    animation: glowSlide 2s ease-in-out infinite;
}

@keyframes glowSlide {
    0%, 100% {
        transform: translateX(-100%);
    }
    50% {
        transform: translateX(100%);
    }
}

.stat-card.malware {
    border-color: rgba(255, 59, 59, 0.3);
}

.stat-card.malware i,
.stat-card.malware .stat-number {
    color: var(--accent-red);
}

.stat-card.malware:hover {
    border-color: var(--accent-red);
    box-shadow: 0 10px 30px var(--danger-glow);
}

.stat-card.suspicious {
    border-color: rgba(255, 215, 0, 0.3);
}

.stat-card.suspicious i,
.stat-card.suspicious .stat-number {
    color: var(--accent-yellow);
}

.stat-card.suspicious:hover {
    border-color: var(--accent-yellow);
    box-shadow: 0 10px 30px var(--warning-glow);
}

.stat-card.benign i,
.stat-card.benign .stat-number,
.stat-card.info i,
.stat-card.info .stat-number {
    color: var(--accent-green);
}

/* Analytics View */
.analytics-header {
    display: flex;
    align-items: center;
    gap: 2rem;
    margin-bottom: 2.5rem;
}

.back-btn {
    background: var(--bg-card);
    border: 2px solid var(--accent-green);
    color: var(--accent-green);
    padding: 0.8rem 1.5rem;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: all 0.3s ease;
}

.back-btn:hover {
    background: var(--accent-green);
    color: var(--bg-primary);
    transform: translateX(-5px);
    box-shadow: 0 5px 20px var(--success-glow);
}

.analytics-header h1 {
    font-size: 2rem;
    color: var(--accent-green);
    font-weight: 700;
}

.analytics-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(500px, 1fr));
    gap: 2rem;
    max-height: calc(100vh - 200px);
    overflow-y: auto;
    padding-right: 1rem;
    grid-auto-flow: dense;
}

/* Panel size classes for flexible tiling */
.analytics-panel.panel-small {
    grid-column: span 1;
}

.analytics-panel.panel-medium {
    grid-column: span 1;
}

.analytics-panel.panel-large {
    grid-column: span 2;
}

@media (max-width: 1400px) {
    .analytics-grid {
        grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
    }

    .analytics-panel.panel-large {
        grid-column: span 1;
    }
}

.analytics-grid::-webkit-scrollbar {
    width: 8px;
}

.analytics-grid::-webkit-scrollbar-track {
    background: var(--bg-secondary);
    border-radius: 4px;
}

.analytics-grid::-webkit-scrollbar-thumb {
    background: var(--accent-green);
    border-radius: 4px;
}

.analytics-grid::-webkit-scrollbar-thumb:hover {
    background: var(--accent-green-dim);
}

.analytics-panel {
    animation: slideInPanel 0.5s ease-out;
    animation-fill-mode: backwards;
}

.analytics-panel:nth-child(1) { animation-delay: 0.05s; }
.analytics-panel:nth-child(2) { animation-delay: 0.1s; }
.analytics-panel:nth-child(3) { animation-delay: 0.15s; }
.analytics-panel:nth-child(4) { animation-delay: 0.2s; }
.analytics-panel:nth-child(5) { animation-delay: 0.25s; }
.analytics-panel:nth-child(6) { animation-delay: 0.3s; }

@keyframes slideInPanel {
    from {
        opacity: 0;
        transform: translateY(30px) scale(0.95);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* Advanced Analytics Grid for Mini Charts */
.advanced-analytics-grid {
    background: rgba(15, 15, 15, 0.5);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(57, 255, 20, 0.2);
    border-radius: 12px;
    padding: 1.5rem;
}

.mini-charts-grid {
