}

.mini-chart-container h3 {
    color: var(--accent-green);
    font-size: 0.95rem;
    margin: 0 0 0.75rem 0;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.mini-chart-container h3 i {
    font-size: 0.9rem;
}

@media (max-width: 1200px) {
    .mini-charts-grid {
        grid-template-columns: 1fr;
    }
}

