/* Back to Top Button */
.back-to-top {
    position: fixed;
    bottom: 30px;
    right: 30px;
    width: 50px;
    height: 50px;
    background: linear-gradient(135deg, var(--accent-green), var(--accent-green-dim));
    border: 2px solid var(--accent-green);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 9998;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
    box-shadow: 0 4px 20px var(--success-glow);
    color: #000;
    font-size: 1.2rem;
}

.back-to-top.visible {
    opacity: 1;
    visibility: visible;
}

.back-to-top:hover {
    transform: translateY(-5px) scale(1.1);
    box-shadow: 0 6px 30px var(--success-glow);
}

.back-to-top:active {
    transform: translateY(-2px) scale(1.05);
}

[data-theme="light"] .back-to-top {
    background: linear-gradient(135deg, #2ed60f, #27b00c);
    color: #fff;
}

